import numpy as np
import neuralfoil as nf

# NACA 2412 coordinates (simple standard airfoil), generated by hand
def naca4(m=0.02, p=0.4, t=0.12, n=100):
    x = (1 - np.cos(np.linspace(0, np.pi, n))) / 2
    yt = 5*t*(0.2969*np.sqrt(x) - 0.1260*x - 0.3516*x**2
              + 0.2843*x**3 - 0.1036*x**4)
    yc = np.where(x < p, m/p**2*(2*p*x - x**2),
                  m/(1-p)**2*((1-2*p) + 2*p*x - x**2))
    upper = np.column_stack([x, yc + yt])
    lower = np.column_stack([x, yc - yt])
    return np.vstack([upper[::-1], lower[1:]])

coords = naca4()
aero = nf.get_aero_from_coordinates(coordinates=coords, alpha=5, Re=1e6)
print("CL =", aero["CL"])
print("CD =", aero["CD"])